### Problem description & steps to reproduce

This is my sampler code:

~~~c++
// Build sampler according to temp_/top_p_/top_k_ and optional grammar
llama_sampler * LLMEngine::build_sampler_(const llama_vocab *vocab) {
    llama_sampler_chain_params sparams = llama_sampler_chain_default_params();
    llama_sampler *chain = llama_sampler_chain_init(sparams);

    // Temperature 0 -> greedy, else typical sampling stack
    if (temp_ == 0.0f) {
        llama_sampler_chain_add(chain, llama_sampler_init_greedy());
    } else {
        if (top_k_ > 0) {
            llama_sampler_chain_add(chain, llama_sampler_init_top_k(top_k_));
        }
        llama_sampler_chain_add(chain, llama_sampler_init_top_p(top_p_, 1));
        llama_sampler_chain_add(chain, llama_sampler_init_temp(temp_));
    }

    // Optional grammar
    if (!grammar_file_.empty()) {
        std::ifstream ifs(grammar_file_);
        if (ifs) {
            std::string gbnf((std::istreambuf_iterator<char>(ifs)), std::istreambuf_iterator<char>());
            llama_sampler *gram = llama_sampler_init_grammar(vocab, gbnf.c_str(), "root");
            if (gram) {
                llama_sampler_chain_add(chain, gram);
            } else {
                std::cerr << "[LLMEngine] Warning: failed to init grammar from " << grammar_file_ << "\n";
            }
        } else {
            std::cerr << "[LLMEngine] Warning: cannot open grammar file: " << grammar_file_ << "\n";
        }
    }

    return chain;
}
~~~

