+//
+// Matches the mistral-common / vLLM Voxtral feature extraction:
+//   1. zero-pad the waveform up to a whole multiple of chunk_length_s (30s)
+//   2. reflection-pad n_fft/2 samples at each end (torch.stft center=True)
+//   3. compute one global mel spectrogram and drop the final STFT frame
+//      (vLLM uses stft[..., :-1])
+//   4. apply the Whisper log-mel normalization (clamp at global max - 8,
+//      then (x + 4) / 4) over the full audio before 3000-frame chunking
+//
+
+void mtmd_audio_preprocessor_voxtral::initialize() {
+    cache.fill_sin_cos_table(hparams.audio_n_fft);
+    cache.fill_hann_window(hparams.audio_window_len, true);
+    cache.fill_mel_filterbank_matrix(hparams.n_mel_bins, hparams.audio_n_fft, hparams.audio_sample_rate);
+}
+
+bool mtmd_audio_preprocessor_voxtral::preprocess(const float *                 samples,
+                                                 size_t                        n_samples,
+                                                 std::vector<mtmd_audio_mel> & output) {
+    if (n_samples == 0) {
+        // empty audio
+        return false;
+    }
+
+    GGML_ASSERT(!cache.sin_vals.empty());
+    GGML_ASSERT(!cache.cos_vals.empty());
+    GGML_ASSERT(!cache.filters.data.empty());
+
+    const int    hop              = hparams.audio_hop_len;
+    const int    pad              = hparams.audio_n_fft / 2;                                        // 200
+    const size_t chunk_samples    = (size_t) hparams.audio_sample_rate * hparams.audio_chunk_len;   // 30s
+    const size_t frames_per_chunk = chunk_samples / (size_t) hop;                                   // 3000
+
+    // (1) zero-pad to a whole number of 30s chunks (at least one chunk)
+    const size_t n_chunks   = std::max<size_t>(1, (n_samples + chunk_samples - 1) / chunk_samples);
+    const size_t padded_len = n_chunks * chunk_samples;
+
+    // (2) reflection-pad n_fft/2 at each end of the (zero-padded) waveform
+    std::vector<float> buf(padded_len + 2 * (size_t) pad, 0.0f);
+    for (int i = 0; i < pad; i++) {
+        int src = pad - i;  // samples[pad], samples[pad-1], ..., samples[1]
+        buf[i] = (src < (int) n_samples) ? samples[src] : 0.0f;
+    }
+    std::copy(samples, samples + n_samples, buf.begin() + pad);
+    for (int i = 0; i < pad; i++) {
+        int src = (int) padded_len - 2 - i;  // reflect the tail (zeros where padded)
+        buf[padded_len + pad + i] = (src >= 0 && src < (int) n_samples) ? samples[src] : 0.0f;
+    }
+
+    filter_params params;
+    params.n_mel            = hparams.n_mel_bins;
+    params.n_fft_bins       = 1 + (hparams.audio_n_fft / 2);
+    params.hann_window_size = hparams.audio_window_len;
+    params.hop_length       = hop;
+    params.sample_rate      = hparams.audio_sample_rate;
+    params.no_padding       = true;   // padding already applied above
+    params.preemph          = 0.0f;   // disabled
+    params.use_natural_log  = false;
+    params.norm_per_feature = false;
+    params.mel_floor        = 1e-10f;
